@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    TimeoutLimits that = (TimeoutLimits) o;
    return totalTaskTimeoutMillis == that.totalTaskTimeoutMillis && progressTimeoutMillis == that.progressTimeoutMillis;
}
